let META = [];

/* ----------------------------- 工具 ----------------------------- */
const rm = (n) => "RM " + Math.round(n).toLocaleString();
// 销售金额隐藏开关（点眼睛切换）。money() 在隐藏时把金额遮成 RM ••••，rm() 不受影响（如广告花费）。
let HIDE_SALES = false;
const money = (v) => (HIDE_SALES ? "RM ••••" : rm(v));
const pct = (a, b) => (b > 0 ? (a / b) * 100 : 0);
const tip = { background: C.surface, border: `1px solid ${C.line}`, borderRadius: 12, fontSize: 12, color: C.ink };
// 柱标签：货币用 k 缩写避免太长；其余整数；营业额为空(null)返回空串
const lblK = (v) => (v == null ? "" : Math.abs(v) >= 1000 ? Math.round(v / 1000) + "k" : Math.round(v));

function Kpi({ icon: Icon, label, value, sub, accent }) {
  return (
    <div className="rounded-2xl p-5 flex flex-col gap-2" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
      <div className="flex items-center gap-2">
        <div className="flex items-center justify-center rounded-lg" style={{ width: 30, height: 30, background: accent + "22", color: accent }}><Icon size={17} /></div>
        <span className="text-xs font-medium tracking-wide" style={{ color: C.sub }}>{label}</span>
      </div>
      <div className="font-semibold leading-tight" style={{ color: C.ink, fontSize: 25 }}>{value}</div>
      {sub && <div className="text-xs" style={{ color: C.sub }}>{sub}</div>}
    </div>
  );
}
function Panel({ title, hint, children, right }) {
  return (
    <div className="rounded-2xl p-5" style={{ background: C.surface, border: `1px solid ${C.line}` }}>
      <div className="flex items-start justify-between mb-1 gap-3">
        <div><h3 className="font-semibold" style={{ color: C.ink, fontSize: 15 }}>{title}</h3>
          {hint && <p className="text-xs mt-0.5" style={{ color: C.sub }}>{hint}</p>}</div>
        {right}
      </div>
      <div className="mt-4">{children}</div>
    </div>
  );
}
function FunnelStage({ label, value, width, color, drop }) {
  return (
    <div className="flex items-center gap-3">
      <div className="text-xs font-medium text-right shrink-0" style={{ color: C.sub, width: 78 }}>{label}</div>
      <div className="flex-1">
        <div className="rounded-lg flex items-center px-3" style={{ width: `${Math.max(width, 7)}%`, height: 40, background: color, minWidth: 64 }}>
          <span className="font-semibold text-sm" style={{ color: "#fff" }}>{value.toLocaleString()}</span>
        </div>
      </div>
      <div className="text-xs shrink-0 text-right" style={{ color: C.clay, width: 84 }}>{drop}</div>
    </div>
  );
}

