/* ===================== 数据接入 · 登录 · 自动刷新 ===================== */
function applyData(d) {
  ADS = d.ads || [];
  BRANCHES = d.branches || [];
  ADS_MONTHS = d.adsMonths || [];
  BRANCH_MONTHS = d.branchMonths || [];
  ADS_DAILY = d.adsDaily || {};
  BRANCH_DAILY = d.branchDaily || {};
  OUTLET_SALES = d.outletSales || [];
  // 防御：同一天若被上传多次（表里有重复行），按分店名去重并重算合计，避免数字翻倍
  DAILY_SALES = (d.dailySales || []).map((x) => {
    const seen = new Set();
    const branches = (x.branches || []).filter((b) => { const k = (b.branch || "").trim(); if (!k || seen.has(k)) return false; seen.add(k); return true; });
    const total = branches.reduce((a, b) => ({ today: a.today + b.today, mtd: a.mtd + b.mtd, consult: a.consult + b.consult, enrol: a.enrol + b.enrol, first: a.first + b.first }), { today: 0, mtd: 0, consult: 0, enrol: 0, first: 0 });
    return { ...x, date: normDate(x.date), branches, total };
  });
  META = d.meta || [];

  // 用逐日 Sales 的"最新一天"覆盖该月的 outlet 月度（Actual Sales = MTD Collection / New Lead Sales = First Course），
  // 让 Overview 的 Actual Sales / New Lead Sales / ROAS 自动跟上传的 Sales 数据走。
  const latestByMonth = {};
  DAILY_SALES.forEach((x) => {
    const m = fmtMonthKey(String(x.date).slice(0, 7)); // "Jun 26"
    if (!latestByMonth[m] || String(x.date) > latestByMonth[m].date) latestByMonth[m] = { date: String(x.date), total: x.total };
  });
  Object.keys(latestByMonth).forEach((m) => {
    const t = latestByMonth[m].total || {};
    const actual = t.mtd || 0, newLead = t.first || 0;
    const row = { m, actual, newLead, other: Math.max(0, actual - newLead) };
    const i = OUTLET_SALES.findIndex((o) => o.m === m);
    if (i >= 0) OUTLET_SALES[i] = row; else OUTLET_SALES.push(row);
  });
}

const PW_KEY = "sans_dash_pw";
const REFRESH_MS = 5 * 60 * 1000; // 每 5 分钟自动刷新

export default function App() {
  const [phase, setPhase] = useState("login"); // login | loading | ready | error
  const [pw, setPw] = useState("");
  const [err, setErr] = useState("");
  const [dataVersion, setDataVersion] = useState(0);
  const [updatedAt, setUpdatedAt] = useState(null);
  const pwRef = useRef("");

  const load = async (password, opts = {}) => {
    const silent = opts.silent;
    if (!silent) setPhase("loading");
    setErr("");
    try {
      const res = await fetch("/api/data", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ password }),
      });
      if (res.status === 401) {
        sessionStorage.removeItem(PW_KEY);
        setErr("Wrong password, please try again");
        setPhase("login");
        return;
      }
      if (!res.ok) {
        let msg = "HTTP " + res.status;
        try { const j = await res.json(); if (j && j.error) msg = j.error; } catch (e) {}
        throw new Error(msg);
      }
      const json = await res.json();
      applyData(json);
      pwRef.current = password;
      sessionStorage.setItem(PW_KEY, password);
      setUpdatedAt(new Date());
      setDataVersion((d) => d + 1);
      setPhase("ready");
    } catch (e) {
      setErr("Load failed: " + e.message);
      if (!silent) setPhase("error");
    }
  };

  // 记住登录：刷新页面后用上次密码自动加载
  useEffect(() => {
    const saved = sessionStorage.getItem(PW_KEY);
    if (saved) load(saved);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // 就绪后每 5 分钟静默刷新一次
  useEffect(() => {
    if (phase !== "ready") return;
    const id = setInterval(() => { if (pwRef.current) load(pwRef.current, { silent: true }); }, REFRESH_MS);
    return () => clearInterval(id);
  }, [phase]);

  if (phase === "ready") {
    return (
      <div>
        <Dashboard dataVersion={dataVersion} />
        <RefreshBar
          updatedAt={updatedAt}
          onRefresh={() => load(pwRef.current, { silent: true })}
          onLogout={() => { sessionStorage.removeItem(PW_KEY); pwRef.current = ""; setPw(""); setPhase("login"); }}
        />
      </div>
    );
  }

  const busy = phase === "loading";
  return (
    <div style={{ background: C.sand, minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", padding: 20, fontFamily: "'Inter','PingFang SC','Microsoft YaHei',system-ui,sans-serif" }}>
      <form onSubmit={(e) => { e.preventDefault(); if (pw) load(pw); }}
        style={{ background: C.surface, border: `1px solid ${C.line}`, borderRadius: 20, padding: 36, width: 340, maxWidth: "100%", boxShadow: "0 10px 40px rgba(85,33,2,0.08)" }}>
        <h1 style={{ color: C.brown, fontSize: 20, fontWeight: 600, margin: 0 }}>{"Marketing Dashboard"}</h1>
        <p style={{ color: C.sub, fontSize: 13, margin: "6px 0 20px" }}>{"Enter access password"}</p>
        <input type="password" value={pw} onChange={(e) => setPw(e.target.value)} autoFocus placeholder={"Password"} disabled={busy}
          style={{ width: "100%", boxSizing: "border-box", padding: "11px 14px", borderRadius: 12, border: `1px solid ${C.line}`, background: C.sand, color: C.ink, fontSize: 14, outline: "none" }} />
        {err && <p style={{ color: C.clay, fontSize: 12, margin: "10px 0 0" }}>{err}</p>}
        <button type="submit" disabled={busy || !pw}
          style={{ width: "100%", marginTop: 16, padding: "11px 0", borderRadius: 12, border: "none", background: C.brown, color: "#fff", fontSize: 14, fontWeight: 600, cursor: busy ? "default" : "pointer", opacity: (busy || !pw) ? 0.6 : 1 }}>
          {busy ? "Signing in…" : "Sign in"}
        </button>
      </form>
    </div>
  );
}

function RefreshBar({ updatedAt, onRefresh, onLogout }) {
  const t = updatedAt ? updatedAt.toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit" }) : "—";
  return (
    <div style={{ position: "fixed", right: 16, bottom: 16, display: "flex", alignItems: "center", gap: 10, background: C.surface, border: `1px solid ${C.line}`, borderRadius: 999, padding: "7px 14px", fontSize: 12, color: C.sub, boxShadow: "0 4px 16px rgba(85,33,2,0.10)", zIndex: 50 }}>
      <span>{"Updated"} {t}</span>
      <button onClick={onRefresh} style={{ border: "none", background: C.sage, color: "#fff", borderRadius: 999, padding: "4px 12px", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>{"Refresh"}</button>
      <button onClick={onLogout} style={{ border: "none", background: "transparent", color: C.sub, fontSize: 12, cursor: "pointer", textDecoration: "underline" }}>{"Log out"}</button>
    </div>
  );
}
